/**
 * Bundles src/in-page/entry.ts (Finder's OLX parser + verification) into one
 * self-contained IIFE and stores it as a string in
 * src/generated/in-page-bundle.ts. Runs automatically before every
 * `wrangler dev` / `wrangler deploy` ([build] in wrangler.toml); a test fails
 * when the committed file is stale.
 *
 *   node scripts/build-in-page-bundle.mjs          # write
 *   node scripts/build-in-page-bundle.mjs --check  # exit 1 when stale
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import { build } from "esbuild";

const root = new URL("..", import.meta.url);
const target = new URL("src/generated/in-page-bundle.ts", root);

export async function buildInPageBundle() {
  const result = await build({
    entryPoints: [fileURLToPath(new URL("src/in-page/entry.ts", root))],
    bundle: true,
    write: false,
    format: "iife",
    globalName: "FlipOlxInPage",
    platform: "browser",
    target: "es2020",
    minify: true,
    keepNames: false,
    legalComments: "none",
    charset: "utf8",
    logLevel: "silent",
  });
  const code = result.outputFiles[0].text.trim();
  const digest = createHash("sha256").update(code).digest("hex").slice(0, 16);
  return `// GENERATED by scripts/build-in-page-bundle.mjs — do not edit (sha256:${digest}).\n`
    + `// Finder's OLX parser bundled for evaluation inside the Browser Run page.\n`
    + `export const IN_PAGE_BUNDLE = ${JSON.stringify(code)};\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const next = await buildInPageBundle();
  let current = "";
  try { current = readFileSync(target, "utf8"); } catch { /* first build */ }
  if (process.argv.includes("--check")) {
    if (current !== next) { process.stderr.write("src/generated/in-page-bundle.ts is stale: run node scripts/build-in-page-bundle.mjs\n"); process.exit(1); }
  } else if (current !== next) {
    writeFileSync(target, next);
    process.stdout.write(`updated ${fileURLToPath(target)}\n`);
  }
}
